using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SmartERP.Sales.Domain.Entities;
namespace SmartERP.Sales.DataAccess.Configurations;
public sealed class SalesFinancialRecordConfiguration : IEntityTypeConfiguration<SalesFinancialRecord> { public void Configure(EntityTypeBuilder<SalesFinancialRecord> b) { b.ToTable("SalesFinancialRecords", "sales"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(200).IsRequired(); b.Property(x => x.Code).HasMaxLength(64).IsRequired(); b.Property(x => x.Description).HasMaxLength(2000); b.Property(x => x.ReferenceNumber).HasMaxLength(100); b.Property(x => x.CurrencyCode).HasMaxLength(3); b.Property(x => x.Status).HasMaxLength(40).IsRequired(); b.Property(x => x.MetadataJson).HasColumnType("nvarchar(max)"); foreach (var p in new[] { nameof(SalesFinancialRecord.Quantity), nameof(SalesFinancialRecord.Subtotal), nameof(SalesFinancialRecord.TaxAmount), nameof(SalesFinancialRecord.DiscountAmount), nameof(SalesFinancialRecord.TotalAmount), nameof(SalesFinancialRecord.Balance), nameof(SalesFinancialRecord.Debit), nameof(SalesFinancialRecord.Credit) }) b.Property<decimal?>(p).HasPrecision(19, 4); b.HasIndex(x => new { x.CompanyId, x.Type, x.Code }).IsUnique(); b.HasIndex(x => new { x.CompanyId, x.Type, x.Status }); b.HasIndex(x => new { x.CompanyId, x.CustomerId }); b.HasIndex(x => new { x.CompanyId, x.AccountId }); b.HasIndex(x => new { x.CompanyId, x.DueDateUtc }); } }
